// Typed wrappers around the Tauri IPC surface. Command names and event channels
// must match the Rust `#[tauri::command]` wrappers / event emitters (see
// apps/src-tauri/src/ipc). Types come from the ts-rs-generated bindings in
// ../types (regenerated by `cargo test`).
import { invoke } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";

import type { MediaSourceDto } from "../types/MediaSourceDto";
import type { StartDownloadArgs } from "../types/StartDownloadArgs";
import type { StartDownloadResponse } from "../types/StartDownloadResponse";
import type { HistoryEntryDto } from "../types/HistoryEntryDto";
import type { DownloadViewDto } from "../types/DownloadViewDto";
import type { SettingsDto } from "../types/SettingsDto";
import type { ProgressPayload } from "../types/ProgressPayload";
import type { TaskStateChangedPayload } from "../types/TaskStateChangedPayload";
import type { MediaDetectedPayload } from "../types/MediaDetectedPayload";
import type { BrowsingContextChangedPayload } from "../types/BrowsingContextChangedPayload";

export const commands = {
  probeUrl: (url: string) => invoke<MediaSourceDto>("probe_url", { url }),
  startDownload: (args: StartDownloadArgs) =>
    invoke<StartDownloadResponse>("start_download", { args }),
  cancelDownload: (taskId: string) => invoke<void>("cancel_download", { taskId }),
  pauseDownload: (taskId: string) => invoke<void>("pause_download", { taskId }),
  resumeDownload: (taskId: string) => invoke<void>("resume_download", { taskId }),
  extractFromPage: (url: string) =>
    invoke<MediaSourceDto[]>("extract_from_page", { url }),
  openInteractiveExtraction: (url: string) =>
    invoke<void>("open_interactive_extraction", { url }),
  listActive: () => invoke<DownloadViewDto[]>("list_active"),
  listHistory: () => invoke<HistoryEntryDto[]>("list_history"),
  removeDownload: (taskId: string) => invoke<void>("remove_download", { taskId }),
  retryDownload: (taskId: string) => invoke<void>("retry_download", { taskId }),
  deleteHistoryEntry: (downloadId: string) =>
    invoke<void>("delete_history_entry", { downloadId }),
  openContainingFolder: (path: string) =>
    invoke<void>("open_containing_folder", { path }),
  openDownloadFolder: (downloadId: string) =>
    invoke<void>("open_download_folder", { downloadId }),
  rescanExtension: () => invoke<void>("rescan_extension"),
  extensionConnected: () => invoke<boolean>("extension_connected"),
  ffmpegIsFull: () => invoke<boolean>("ffmpeg_is_full"),
  getSettings: () => invoke<SettingsDto>("get_settings"),
  updateSettings: (settings: SettingsDto) =>
    invoke<void>("update_settings", { settings }),
  updateYtdlp: () => invoke<string>("update_ytdlp"),
};

export const channels = {
  mediaDetected: "media://detected",
  downloadCreated: "download://created",
  taskStateChanged: "task://state-changed",
  progress: "download://progress",
  browsingContextChanged: "browsing://context-changed",
} as const;

export const events = {
  onProgress: (cb: (p: ProgressPayload) => void): Promise<UnlistenFn> =>
    listen<ProgressPayload>(channels.progress, (e) => cb(e.payload)),
  onTaskState: (cb: (p: TaskStateChangedPayload) => void): Promise<UnlistenFn> =>
    listen<TaskStateChangedPayload>(channels.taskStateChanged, (e) => cb(e.payload)),
  onMediaDetected: (cb: (p: MediaDetectedPayload) => void): Promise<UnlistenFn> =>
    listen<MediaDetectedPayload>(channels.mediaDetected, (e) => cb(e.payload)),
  onBrowsingContextChanged: (
    cb: (p: BrowsingContextChangedPayload) => void,
  ): Promise<UnlistenFn> =>
    listen<BrowsingContextChangedPayload>(channels.browsingContextChanged, (e) =>
      cb(e.payload),
    ),
};
